import pytest
from flask.json.tag import TaggedJSONSerializer
from flask.json.tag import JSONTag

class MockTag(JSONTag):
    key = "mock"

    def __init__(self, serializer):
        self.serializer = serializer

class MockTagWithKey(JSONTag):
    key = "existing"

    def __init__(self, serializer):
        self.serializer = serializer

class TestTaggedJSONSerializer:

    def setup_method(self):
        self.serializer = TaggedJSONSerializer()

    def test_register_new_tag(self):
        self.serializer.register(MockTag)
        assert "mock" in self.serializer.tags
        assert isinstance(self.serializer.tags["mock"], MockTag)
        assert self.serializer.order[-1] is self.serializer.tags["mock"]

    def test_register_existing_tag_without_force(self):
        self.serializer.register(MockTagWithKey)
        with pytest.raises(KeyError, match="Tag 'existing' is already registered."):
            self.serializer.register(MockTagWithKey)

    def test_register_existing_tag_with_force(self):
        self.serializer.register(MockTagWithKey)
        self.serializer.register(MockTagWithKey, force=True)
        assert "existing" in self.serializer.tags
        assert isinstance(self.serializer.tags["existing"], MockTagWithKey)

    def test_register_tag_with_index(self):
        self.serializer.register(MockTag)
        self.serializer.register(MockTagWithKey, index=0)
        assert self.serializer.order[0] is self.serializer.tags["existing"]
        assert self.serializer.order[1] is self.serializer.tags["mock"]

    def test_register_tag_with_none_key(self):
        class MockTagNoneKey(JSONTag):
            key = None

            def __init__(self, serializer):
                self.serializer = serializer

        self.serializer.register(MockTagNoneKey)
        assert None not in self.serializer.tags
        assert self.serializer.order[-1] is self.serializer.tags.get(None)

